import{_ as t,o,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Billing - My Invoices","description":"","frontmatter":{"title":"Billing - My Invoices"},"headers":[],"relativePath":"operations-knowledge-base/billing-issues/billing-my-invoices.md","filePath":"operations-knowledge-base/billing-issues/billing-my-invoices.md","lastUpdated":1794292919000}'),a={name:"operations-knowledge-base/billing-issues/billing-my-invoices.md"};function r(s,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<p>Welcome to the RakSmart <strong>Customer Center</strong>. On the <strong>My Invoices</strong> page, you can view and manage the invoice records for all your orders, including <strong>Dedicated Servers</strong>, <strong>Bare Metal Cloud</strong>, <strong>VPS</strong>, and other products. Below is a detailed overview of the page functions and how to use them.</p><hr><h2 id="_1-page-overview" tabindex="-1">1. Page Overview <a class="header-anchor" href="#_1-page-overview" aria-label="Permalink to &quot;1. Page Overview&quot;">​</a></h2><p>In the &quot;Customer Center&quot;, click &quot;Billing&quot; → &quot;My Invoices&quot; to open the invoice list page.</p><p>This page displays all invoice records under your account in a table format and provides filtering and mass payment functions.</p><h3 id="top-toolbar-functions" tabindex="-1">Top Toolbar Functions <a class="header-anchor" href="#top-toolbar-functions" aria-label="Permalink to &quot;Top Toolbar Functions&quot;">​</a></h3><p><strong>Status Tabs:</strong> You can filter invoices by status using the tabs &quot;All&quot;, &quot;Paid&quot;, &quot;Unpaid&quot;, &quot;Cancelled&quot;, &quot;Refunded&quot;, and &quot;Expired&quot;.</p><p><strong>Search Box:</strong> You can enter keywords such as <strong>Invoice #</strong>, <strong>hostname</strong>, or <strong>Primary IP</strong>, then click &quot;Search&quot; for quick lookup.</p><hr><h2 id="_2-invoice-list-field-description" tabindex="-1">2. Invoice List Field Description <a class="header-anchor" href="#_2-invoice-list-field-description" aria-label="Permalink to &quot;2. Invoice List Field Description&quot;">​</a></h2><p>Each invoice entry in the list displays the following key information:</p><table tabindex="0"><thead><tr><th>Field Name</th><th>Description</th></tr></thead><tbody><tr><td><strong>Invoice #</strong></td><td>The unique invoice number. Click it to open the invoice details page.</td></tr><tr><td><strong>hostname</strong></td><td>The hostname associated with the order (for example: V20260208056951).</td></tr><tr><td><strong>Primary IP</strong></td><td>The primary IPv4 address assigned to the product.</td></tr><tr><td><strong>Invoice Date</strong></td><td>The date when the invoice was generated.</td></tr><tr><td><strong>Due Date</strong></td><td>The payment deadline for the invoice. Failure to pay before the due date may result in service suspension.</td></tr><tr><td><strong>Total</strong></td><td>The total amount payable for the invoice (currency: USD).</td></tr><tr><td><strong>Status</strong></td><td>The current payment status of the invoice (such as <strong>Unpaid</strong>, <strong>Paid</strong>, or <strong>Refunded</strong>).</td></tr><tr><td><strong>Operation</strong></td><td>Buttons for performing actions on the invoice.</td></tr></tbody></table><hr><h2 id="_3-core-operations" tabindex="-1">3. Core Operations <a class="header-anchor" href="#_3-core-operations" aria-label="Permalink to &quot;3. Core Operations&quot;">​</a></h2><h3 id="_1-view-service" tabindex="-1">1. View Service <a class="header-anchor" href="#_1-view-service" aria-label="Permalink to &quot;1. View Service&quot;">​</a></h3><p><strong>Location:</strong> On the left side of the <strong>Operation</strong> column for each invoice.</p><p><strong>Function:</strong> Click &quot;View Service&quot; to automatically go to the product management page associated with that order.</p><p><strong>Use Cases:</strong></p><ul><li>Check the server’s hardware configuration and running status</li><li>Perform operations such as rebooting, reinstalling the OS, or resetting passwords</li><li>Manage additional services attached to the product</li></ul><h3 id="_2-view-invoice" tabindex="-1">2. View Invoice <a class="header-anchor" href="#_2-view-invoice" aria-label="Permalink to &quot;2. View Invoice&quot;">​</a></h3><p><strong>Location:</strong> On the right side of the <strong>Operation</strong> column.</p><p><strong>Function:</strong> Click &quot;View Invoice&quot; to open the detailed invoice page for that invoice.</p><p><strong>Use Cases:</strong></p><ul><li>Review invoice details, such as renewals, upgrades, and additional IP charges</li><li>Pay a single invoice directly through the available payment gateway</li></ul><h3 id="_3-mass-payment" tabindex="-1">3. Mass Payment <a class="header-anchor" href="#_3-mass-payment" aria-label="Permalink to &quot;3. Mass Payment&quot;">​</a></h3><p><strong>Location:</strong> At the bottom of the invoice list.</p><p><strong>Function:</strong> Provides a combined payment feature, allowing you to pay multiple invoices at once.</p><p><strong>Operation Steps:</strong></p><ol><li>In the invoice list, select all invoices you want to pay. Usually, only invoices with the &quot;Unpaid&quot; status can be selected.</li><li>Click the &quot;Mass Payment&quot; button at the bottom of the list.</li><li>The system will redirect you to the checkout center, where the total amount of all selected invoices will be combined into a single payment order.</li><li>You only need to complete one payment to settle all selected invoices.</li></ol><h2 id="_4-status-description" tabindex="-1">4. Status Description <a class="header-anchor" href="#_4-status-description" aria-label="Permalink to &quot;4. Status Description&quot;">​</a></h2><p><strong>Paid:</strong> The invoice has been successfully paid. The corresponding service is active or has been renewed.</p><p><strong>Unpaid:</strong> The invoice is awaiting payment. Please complete the payment before the due date to avoid service interruption.</p><p><strong>Refunded:</strong> A refund has been issued for this transaction, and the amount will be returned to your original payment account.</p><p><strong>Cancelled:</strong> The invoice has been cancelled, usually due to order cancellation or administrative action.</p><p><strong>Expired:</strong> The invoice has passed the payment deadline without being paid. The associated service may have been suspended.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>If your invoice list is long, you can use the &quot;Show&quot; drop-down menu in the upper-right corner of the page to adjust how many records are displayed per page, such as 10 or 20.</li><li>If you have any questions about your invoices, you can click &quot;Online Support&quot; on the right side of the page for assistance.</li></ul>',37)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
